import DashboardLayout from "@/components/DashboardLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { trpc } from "@/lib/trpc";
import { useAuth } from "@/_core/hooks/useAuth";
import { ArrowDownToLine, ArrowRight, BarChart3, BookOpen, CalendarDays, Check, ChevronDown, ChevronLeft, CirclePlus, ClipboardList, Download, FileBarChart, FileText, Filter, GraduationCap, LineChart, Loader2, MoreHorizontal, Plus, RefreshCw, Search, School, Settings2, Sparkles, Target, TrendingUp, UserRound, Users, UsersRound } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useLocation } from "wouter";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis } from "recharts";

function maskCpf(cpf: string | null | undefined) {
  const digits = (cpf ?? "").replace(/\D/g, "");
  if (digits.length !== 11) return "•••.•••.•••-••";
  return `${digits.slice(0, 3)}.•••.•••-${digits.slice(-2)}`;
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-xs font-extrabold uppercase tracking-[0.18em] text-primary">{eyebrow}</p><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-primary sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p></div>{action}</div>;
}

function SectionCard({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <section className={`rounded-3xl border border-border/70 bg-card p-5 soft-shadow sm:p-6 ${className}`}>{children}</section>;
}

function EmptyState({ icon: Icon, title, text }: { icon: typeof Search; title: string; text: string }) {
  return <div className="grid place-items-center rounded-2xl border border-dashed border-border bg-muted/30 px-6 py-12 text-center"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-secondary text-primary"><Icon className="h-5 w-5" /></div><p className="mt-4 font-bold text-primary">{title}</p><p className="mt-1 max-w-sm text-sm leading-6 text-muted-foreground">{text}</p></div>;
}

function DashboardHome() {
  const { user } = useAuth();
  const emptyFilter = useMemo(() => ({}), []);
  const dashboardQuery = trpc.dashboard.useQuery(undefined, { enabled: Boolean(user) });
  const resultsQuery = trpc.teacher.results.useQuery(emptyFilter, { enabled: Boolean(user) });
  const dashboard = dashboardQuery.data;
  const totals = dashboard?.totals;
  const recentResults = resultsQuery.data?.slice(0, 5) ?? [];
  const rangeTotal = dashboard?.byRange.reduce((sum, item) => sum + item.value, 0) || 1;

  return <div>
    <PageHeader eyebrow="Visão geral" title={`Olá, ${user?.name?.split(" ")[0] ?? "equipe"}.`} description="Acompanhe o pulso da aprendizagem e encontre rapidamente onde uma intervenção pedagógica pode fazer diferença." action={<Button variant="outline" className="rounded-full border-primary/20" onClick={() => dashboardQuery.refetch()}><RefreshCw className="mr-2 h-4 w-4" /> Atualizar dados</Button>} />
    {dashboardQuery.isLoading ? <div className="grid place-items-center rounded-3xl border border-border bg-card py-24"><Loader2 className="h-6 w-6 animate-spin text-primary" /></div> : dashboardQuery.error ? <div className="rounded-3xl border border-destructive/20 bg-destructive/5 p-6 text-sm text-destructive">Não foi possível carregar os indicadores. Verifique sua permissão ou tente atualizar.</div> : <>
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {[{ label: "Alunos ativos", value: totals?.students ?? 0, note: "inscritos na base", icon: GraduationCap, tone: "bg-secondary text-primary" }, { label: "Avaliações", value: totals?.assessments ?? 0, note: "criadas no ambiente", icon: ClipboardList, tone: "bg-accent text-accent-foreground" }, { label: "Média geral", value: `${(totals?.average ?? 0).toFixed(1).replace(".", ",")}%`, note: "aproveitamento médio", icon: TrendingUp, tone: "bg-[oklch(0.93_0.035_165)] text-[oklch(0.3_0.08_165)]" }, { label: "Participação", value: `${(totals?.participation ?? 0).toFixed(1).replace(".", ",")}%`, note: "alunos com tentativa", icon: Target, tone: "bg-primary text-primary-foreground" }].map((metric) => <div key={metric.label} className="lift-on-hover rounded-3xl border border-border/70 bg-card p-5 soft-shadow"><div className="flex items-start justify-between gap-3"><div className={`grid h-10 w-10 place-items-center rounded-2xl ${metric.tone}`}><metric.icon className="h-5 w-5" /></div><MoreHorizontal className="h-4 w-4 text-muted-foreground" /></div><p className="mt-6 text-sm font-semibold text-muted-foreground">{metric.label}</p><p className="mt-1 font-[Manrope] text-3xl font-extrabold tracking-tight text-primary">{metric.value}</p><p className="mt-2 text-xs font-medium text-muted-foreground">{metric.note}</p></div>)}</div>
      <div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.65fr]">
        <SectionCard><div className="mb-5 flex items-start justify-between gap-4"><div><p className="text-sm font-extrabold text-primary">Média por disciplina</p><p className="mt-1 text-xs text-muted-foreground">Leitura consolidada das avaliações enviadas</p></div><span className="rounded-full bg-secondary px-3 py-1 text-xs font-bold text-primary">Aproveitamento</span></div><div className="h-[260px] w-full">{dashboard?.bySubject.length ? <ResponsiveContainer width="100%" height="100%"><BarChart data={dashboard.bySubject} layout="vertical" margin={{ left: 10, right: 20, top: 10, bottom: 0 }}><CartesianGrid horizontal={false} strokeDasharray="3 3" stroke="oklch(0.85 0.02 232)" /><XAxis type="number" domain={[0, 100]} tickFormatter={(value) => `${value}%`} tick={{ fontSize: 11, fill: "oklch(0.5 0.03 232)" }} axisLine={false} tickLine={false} /><YAxis type="category" dataKey="subject" width={130} tick={{ fontSize: 12, fill: "oklch(0.3 0.04 232)" }} axisLine={false} tickLine={false} /><ChartTooltip formatter={(value) => [`${value}%`, "Média"]} contentStyle={{ borderRadius: 14, border: "1px solid oklch(0.89 0.018 232)", boxShadow: "0 12px 30px oklch(0.23 0.035 232 / 10%)" }} /><Bar dataKey="value" radius={[0, 8, 8, 0]} fill="oklch(0.55 0.12 192)" barSize={26} /></BarChart></ResponsiveContainer> : <EmptyState icon={BarChart3} title="Sem resultados ainda" text="As médias aparecerão assim que os primeiros alunos concluírem uma avaliação." />}</div></SectionCard>
        <SectionCard><div className="mb-5"><p className="text-sm font-extrabold text-primary">Faixas de aproveitamento</p><p className="mt-1 text-xs text-muted-foreground">Distribuição dos alunos participantes</p></div><div className="h-[170px]">{dashboard?.byRange.some((item) => item.value) ? <ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={dashboard.byRange} dataKey="value" nameKey="label" innerRadius={50} outerRadius={72} paddingAngle={3}>{dashboard.byRange.map((entry, index) => <Cell key={entry.label} fill={["oklch(0.55 0.12 192)", "oklch(0.64 0.14 50)", "oklch(0.67 0.14 85)", "oklch(0.58 0.1 25)"][index]} />)}</Pie><ChartTooltip formatter={(value) => [`${value} alunos`, "Faixa"]} contentStyle={{ borderRadius: 14, border: "1px solid oklch(0.89 0.018 232)" }} /></PieChart></ResponsiveContainer> : <div className="grid h-full place-items-center text-sm text-muted-foreground">Sem dados suficientes</div>}</div><div className="mt-2 space-y-3">{dashboard?.byRange.map((item, index) => <div key={item.label} className="flex items-center gap-3"><span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: ["oklch(0.55 0.12 192)", "oklch(0.64 0.14 50)", "oklch(0.67 0.14 85)", "oklch(0.58 0.1 25)"][index] }} /><span className="flex-1 text-xs font-semibold text-muted-foreground">{item.label}</span><span className="text-xs font-extrabold text-primary">{Math.round((item.value / rangeTotal) * 100)}%</span></div>)}</div></SectionCard>
      </div>
      <div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
        <SectionCard><div className="mb-5 flex items-start justify-between"><div><p className="text-sm font-extrabold text-primary">Desempenho por turma</p><p className="mt-1 text-xs text-muted-foreground">Onde concentrar a próxima conversa pedagógica</p></div><Button variant="ghost" className="h-8 rounded-full px-3 text-xs font-bold text-primary" onClick={() => window.location.assign("/admin/results")}>Ver detalhes <ArrowRight className="ml-1.5 h-3.5 w-3.5" /></Button></div><div className="space-y-4">{dashboard?.classes.slice(0, 6).map((classRow) => <div key={classRow.classId} className="flex items-center gap-4"><div className="w-20 shrink-0 text-sm font-bold text-primary">{classRow.label}</div><div className="h-2 flex-1 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${classRow.value}%` }} /></div><div className="w-11 text-right text-sm font-extrabold text-primary">{classRow.value}%</div></div>)}{!dashboard?.classes.length ? <EmptyState icon={UsersRound} title="Nenhuma turma cadastrada" text="Cadastre a primeira turma para acompanhar o desempenho por grupo." /> : null}</div></SectionCard>
        <SectionCard><div className="mb-5 flex items-start justify-between"><div><p className="text-sm font-extrabold text-primary">Últimos resultados</p><p className="mt-1 text-xs text-muted-foreground">As aplicações mais recentes</p></div><CalendarDays className="h-5 w-5 text-primary" /></div>{recentResults.length ? <div className="space-y-3">{recentResults.map((row) => <div key={row.attempt.id} className="flex items-center gap-3 rounded-2xl bg-muted/50 p-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-secondary text-primary"><UserRound className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-primary">{row.student?.name}</p><p className="truncate text-xs text-muted-foreground">{row.classRow?.name} · {row.subject?.name}</p></div><span className="text-sm font-extrabold text-primary">{Number(row.attempt.percentage).toFixed(0)}%</span></div>)}</div> : <EmptyState icon={FileBarChart} title="Sem aplicações concluídas" text="Os resultados recentes aparecerão aqui." />}</SectionCard>
      </div>
    </>}</div>;
}

function AssessmentsPage() {
  const assessmentsQuery = trpc.admin.assessments.list.useQuery();
  const subjectsQuery = trpc.admin.subjects.list.useQuery();
  const questionsQuery = trpc.admin.questions.list.useQuery();
  const utils = trpc.useUtils();
  const createMutation = trpc.admin.assessments.create.useMutation({ onSuccess: () => { setShowForm(false); setForm({ name: "", description: "", subjectId: "", startDate: "", endDate: "", timeLimit: "60", maxScore: "10", allowSingleAttempt: true, shuffleQuestions: false, shuffleOptions: false, showResultImmediately: true, allowReview: true, questionIds: [] }); void utils.admin.assessments.list.invalidate(); } });
  const publishMutation = trpc.admin.assessments.publish.useMutation({ onSuccess: () => void utils.admin.assessments.list.invalidate() });
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ name: "", description: "", subjectId: "", startDate: "", endDate: "", timeLimit: "60", maxScore: "10", allowSingleAttempt: true, shuffleQuestions: false, shuffleOptions: false, showResultImmediately: true, allowReview: true, questionIds: [] as number[] });
  const selectedQuestions = useMemo(() => new Set(form.questionIds), [form.questionIds]);
  const toggleQuestion = (id: number) => setForm((current) => ({ ...current, questionIds: current.questionIds.includes(id) ? current.questionIds.filter((item) => item !== id) : [...current.questionIds, id] }));
  const submit = () => { if (!form.name || !form.subjectId || !form.questionIds.length) return; createMutation.mutate({ name: form.name, description: form.description || undefined, subjectId: Number(form.subjectId), startDate: form.startDate ? new Date(form.startDate) : undefined, endDate: form.endDate ? new Date(form.endDate) : undefined, timeLimit: Number(form.timeLimit), maxScore: Number(form.maxScore), questionIds: form.questionIds, allowSingleAttempt: form.allowSingleAttempt, shuffleQuestions: form.shuffleQuestions, shuffleOptions: form.shuffleOptions, showResultImmediately: form.showResultImmediately, allowReview: form.allowReview }); };
  return <div><PageHeader eyebrow="Gestão de avaliações" title="Avaliações" description="Crie, organize e publique provas com o rigor de uma matriz pedagógica bem definida." action={<Button className="rounded-full" onClick={() => setShowForm((value) => !value)}><Plus className="mr-2 h-4 w-4" /> Nova avaliação</Button>} />
    {showForm ? <SectionCard className="mb-5 border-primary/20"><div className="mb-5 flex items-center justify-between"><div><p className="text-sm font-extrabold text-primary">Configurar avaliação</p><p className="mt-1 text-xs text-muted-foreground">Vincule questões do banco e publique quando estiver pronta.</p></div><span className="rounded-full bg-secondary px-3 py-1 text-xs font-bold text-primary">Rascunho</span></div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Nome da avaliação</Label><Input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Ex.: Avaliação diagnóstica 2026" /></div><div className="space-y-2"><Label>Disciplina</Label><select value={form.subjectId} onChange={(event) => setForm({ ...form, subjectId: event.target.value })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Selecione uma disciplina</option>{subjectsQuery.data?.map((subject) => <option key={subject.id} value={subject.id}>{subject.name}</option>)}</select></div><div className="space-y-2 md:col-span-2"><Label>Descrição</Label><Input value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} placeholder="Objetivo e contexto pedagógico" /></div><div className="space-y-2"><Label>Tempo limite (minutos)</Label><Input type="number" min={1} value={form.timeLimit} onChange={(event) => setForm({ ...form, timeLimit: event.target.value })} /></div><div className="space-y-2"><Label>Nota máxima</Label><Input type="number" min={1} value={form.maxScore} onChange={(event) => setForm({ ...form, maxScore: event.target.value })} /></div><div className="space-y-2"><Label>Início da aplicação</Label><Input type="datetime-local" value={form.startDate} onChange={(event) => setForm({ ...form, startDate: event.target.value })} /></div><div className="space-y-2"><Label>Fim da aplicação</Label><Input type="datetime-local" value={form.endDate} onChange={(event) => setForm({ ...form, endDate: event.target.value })} /></div></div><div className="mt-5 grid gap-3 rounded-2xl bg-muted/50 p-4 sm:grid-cols-2"><label className="flex items-center gap-3 text-sm font-semibold text-primary"><input type="checkbox" checked={form.allowSingleAttempt} onChange={(event) => setForm({ ...form, allowSingleAttempt: event.target.checked })} /> Permitir apenas uma tentativa</label><label className="flex items-center gap-3 text-sm font-semibold text-primary"><input type="checkbox" checked={form.shuffleQuestions} onChange={(event) => setForm({ ...form, shuffleQuestions: event.target.checked })} /> Embaralhar questões</label><label className="flex items-center gap-3 text-sm font-semibold text-primary"><input type="checkbox" checked={form.shuffleOptions} onChange={(event) => setForm({ ...form, shuffleOptions: event.target.checked })} /> Embaralhar alternativas</label><label className="flex items-center gap-3 text-sm font-semibold text-primary"><input type="checkbox" checked={form.showResultImmediately} onChange={(event) => setForm({ ...form, showResultImmediately: event.target.checked })} /> Exibir resultado ao final</label><label className="flex items-center gap-3 text-sm font-semibold text-primary"><input type="checkbox" checked={form.allowReview} onChange={(event) => setForm({ ...form, allowReview: event.target.checked })} /> Permitir revisão antes do envio</label></div><div className="mt-6"><div className="mb-3 flex items-center justify-between"><Label>Questões selecionadas</Label><span className="text-xs font-bold text-primary">{form.questionIds.length} selecionada(s)</span></div><div className="max-h-56 space-y-2 overflow-auto rounded-2xl bg-muted/50 p-3">{questionsQuery.data?.map((question) => <button key={question.id} type="button" onClick={() => toggleQuestion(question.id)} className={`flex w-full items-start gap-3 rounded-xl p-3 text-left ${selectedQuestions.has(question.id) ? "bg-secondary" : "hover:bg-background"}`}><span className={`mt-0.5 grid h-5 w-5 shrink-0 place-items-center rounded-md border ${selectedQuestions.has(question.id) ? "border-primary bg-primary text-primary-foreground" : "border-border bg-card"}`}>{selectedQuestions.has(question.id) ? <Check className="h-3.5 w-3.5" /> : null}</span><span className="min-w-0"><span className="block text-xs font-bold text-primary">Q{String(question.id).padStart(2, "0")} · {question.difficulty === "easy" ? "Fácil" : question.difficulty === "hard" ? "Difícil" : "Média"}</span><span className="mt-1 block truncate text-sm text-muted-foreground">{question.statement}</span></span></button>)}{!questionsQuery.data?.length ? <p className="p-5 text-center text-sm text-muted-foreground">Cadastre questões antes de criar uma avaliação.</p> : null}</div></div><div className="mt-6 flex justify-end gap-3"><Button variant="outline" className="rounded-full" onClick={() => setShowForm(false)}>Cancelar</Button><Button className="rounded-full" disabled={createMutation.isPending || !form.name || !form.subjectId || !form.questionIds.length} onClick={submit}>{createMutation.isPending ? "Salvando…" : "Salvar avaliação"}</Button></div>{createMutation.error ? <p className="mt-3 text-sm text-destructive">{createMutation.error.message}</p> : null}</SectionCard> : null}
    <SectionCard><div className="mb-5 flex items-center justify-between"><div><p className="text-sm font-extrabold text-primary">Todas as avaliações</p><p className="mt-1 text-xs text-muted-foreground">{assessmentsQuery.data?.length ?? 0} registros no ambiente</p></div><Button variant="ghost" className="rounded-full text-xs font-bold text-primary"><Filter className="mr-2 h-3.5 w-3.5" /> Filtrar</Button></div>{assessmentsQuery.isLoading ? <div className="p-8 text-center text-sm text-muted-foreground">Carregando avaliações…</div> : assessmentsQuery.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead><tr className="border-b border-border/70 text-xs uppercase tracking-[0.12em] text-muted-foreground"><th className="px-3 py-3 font-bold">Avaliação</th><th className="px-3 py-3 font-bold">Disciplina</th><th className="px-3 py-3 font-bold">Questões</th><th className="px-3 py-3 font-bold">Tempo</th><th className="px-3 py-3 font-bold">Status</th><th className="px-3 py-3" /></tr></thead><tbody>{assessmentsQuery.data.map((assessment) => <tr key={assessment.id} className="border-b border-border/60 last:border-0"><td className="px-3 py-4"><p className="font-bold text-primary">{assessment.name}</p><p className="mt-1 max-w-xs truncate text-xs text-muted-foreground">{assessment.description || "Sem descrição"}</p></td><td className="px-3 py-4 text-muted-foreground">{subjectsQuery.data?.find((subject) => subject.id === assessment.subjectId)?.name || "—"}</td><td className="px-3 py-4 text-muted-foreground">—</td><td className="px-3 py-4 text-muted-foreground">{assessment.timeLimit} min</td><td className="px-3 py-4"><Badge variant={assessment.status === "published" ? "default" : "secondary"} className="rounded-full">{assessment.status === "published" ? "Publicada" : assessment.status === "closed" ? "Encerrada" : "Rascunho"}</Badge></td><td className="px-3 py-4 text-right">{assessment.status === "draft" ? <Button size="sm" variant="outline" className="rounded-full text-xs" onClick={() => publishMutation.mutate({ id: assessment.id })}>Publicar</Button> : <Button size="sm" variant="ghost" className="rounded-full text-xs text-primary">Ver detalhes</Button>}</td></tr>)}</tbody></table></div> : <EmptyState icon={ClipboardList} title="Nenhuma avaliação criada" text="Comece criando uma avaliação e selecione questões do banco para montá-la." />}</SectionCard>
  </div>;
}

function QuestionsPage() {
  const questionsQuery = trpc.admin.questions.list.useQuery();
  const subjectsQuery = trpc.admin.subjects.list.useQuery();
  const utils = trpc.useUtils();
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ statement: "", subjectId: "", questionType: "multiple_choice" as "multiple_choice" | "true_false" | "short_answer", difficulty: "medium" as "easy" | "medium" | "hard", skill: "", descriptor: "", imageUrl: "", correctAnswer: "A", options: ["", "", "", "", ""] });
  const createMutation = trpc.admin.questions.create.useMutation({ onSuccess: () => { setShowForm(false); setForm({ statement: "", subjectId: "", questionType: "multiple_choice", difficulty: "medium", skill: "", descriptor: "", imageUrl: "", correctAnswer: "A", options: ["", "", "", "", ""] }); void utils.admin.questions.list.invalidate(); } });
  const submit = () => { if (!form.statement || !form.subjectId || (form.questionType === "multiple_choice" && form.options.some((option) => !option))) return; createMutation.mutate({ subjectId: Number(form.subjectId), statement: form.statement, questionType: form.questionType, difficulty: form.difficulty, skill: form.skill || undefined, descriptor: form.descriptor || undefined, imageUrl: form.imageUrl || undefined, correctAnswer: form.correctAnswer, points: 1, options: form.questionType === "multiple_choice" ? form.options.map((option, index) => ({ optionLabel: ["A", "B", "C", "D", "E"][index] as "A" | "B" | "C" | "D" | "E", optionText: option, isCorrect: form.correctAnswer === ["A", "B", "C", "D", "E"][index] })) : [] }); };
  return <div><PageHeader eyebrow="Acervo pedagógico" title="Banco de questões" description="Organize itens por disciplina, habilidade e dificuldade para construir avaliações consistentes." action={<Button className="rounded-full" onClick={() => setShowForm((value) => !value)}><CirclePlus className="mr-2 h-4 w-4" /> Nova questão</Button>} />
    {showForm ? <SectionCard className="mb-5 border-primary/20"><div className="mb-5"><p className="text-sm font-extrabold text-primary">Nova questão</p><p className="mt-1 text-xs text-muted-foreground">Cadastre o item e seu gabarito para reutilizar em diferentes avaliações.</p></div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2 md:col-span-2"><Label>Enunciado</Label><textarea value={form.statement} onChange={(event) => setForm({ ...form, statement: event.target.value })} className="min-h-24 w-full rounded-xl border border-input bg-background p-3 text-sm outline-none focus:ring-2 focus:ring-ring" placeholder="Escreva o enunciado da questão…" /></div><div className="space-y-2"><Label>Disciplina</Label><select value={form.subjectId} onChange={(event) => setForm({ ...form, subjectId: event.target.value })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Selecione</option>{subjectsQuery.data?.map((subject) => <option key={subject.id} value={subject.id}>{subject.name}</option>)}</select></div><div className="space-y-2"><Label>Tipo de questão</Label><select value={form.questionType} onChange={(event) => setForm({ ...form, questionType: event.target.value as "multiple_choice" | "true_false" | "short_answer" })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="multiple_choice">Múltipla escolha</option><option value="true_false">Verdadeiro ou falso</option><option value="short_answer">Resposta curta</option></select></div><div className="space-y-2"><Label>Dificuldade</Label><select value={form.difficulty} onChange={(event) => setForm({ ...form, difficulty: event.target.value as "easy" | "medium" | "hard" })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="easy">Fácil</option><option value="medium">Média</option><option value="hard">Difícil</option></select></div><div className="space-y-2"><Label>Habilidade</Label><Input value={form.skill} onChange={(event) => setForm({ ...form, skill: event.target.value })} placeholder="Ex.: EF05MA07" /></div><div className="space-y-2"><Label>Descritor</Label><Input value={form.descriptor} onChange={(event) => setForm({ ...form, descriptor: event.target.value })} placeholder="Descritor pedagógico" /></div><div className="space-y-2 md:col-span-2"><Label>Imagem da questão (URL opcional)</Label><Input type="url" value={form.imageUrl} onChange={(event) => setForm({ ...form, imageUrl: event.target.value })} placeholder="https://…" /></div></div><div className="mt-6"><div className="mb-3 flex items-center justify-between"><Label>Alternativas</Label><span className="text-xs font-bold text-primary">Gabarito</span></div><div className="grid gap-3 sm:grid-cols-2">{form.options.map((option, index) => <div key={index} className="flex items-center gap-2"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-muted text-xs font-extrabold text-primary">{["A", "B", "C", "D", "E"][index]}</span><Input value={option} onChange={(event) => setForm({ ...form, options: form.options.map((current, currentIndex) => currentIndex === index ? event.target.value : current) })} placeholder={`Alternativa ${["A", "B", "C", "D", "E"][index]}`} /><input type="radio" name="correct-answer" checked={form.correctAnswer === ["A", "B", "C", "D", "E"][index]} onChange={() => setForm({ ...form, correctAnswer: ["A", "B", "C", "D", "E"][index] })} aria-label={`Marcar alternativa ${["A", "B", "C", "D", "E"][index]} como correta`} /></div>)}</div></div><div className="mt-6 flex justify-end gap-3"><Button variant="outline" className="rounded-full" onClick={() => setShowForm(false)}>Cancelar</Button><Button className="rounded-full" disabled={createMutation.isPending || !form.statement || !form.subjectId || (form.questionType === "multiple_choice" && form.options.some((option) => !option))} onClick={submit}>{createMutation.isPending ? "Salvando…" : "Salvar questão"}</Button></div>{createMutation.error ? <p className="mt-3 text-sm text-destructive">{createMutation.error.message}</p> : null}</SectionCard> : null}
    <SectionCard><div className="mb-5 flex items-center justify-between"><div><p className="text-sm font-extrabold text-primary">Questões cadastradas</p><p className="mt-1 text-xs text-muted-foreground">{questionsQuery.data?.length ?? 0} itens ativos</p></div><div className="relative hidden w-64 sm:block"><Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" /><Input className="h-9 rounded-full pl-9" placeholder="Buscar enunciado" /></div></div>{questionsQuery.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead><tr className="border-b border-border/70 text-xs uppercase tracking-[0.12em] text-muted-foreground"><th className="px-3 py-3">Questão</th><th className="px-3 py-3">Disciplina</th><th className="px-3 py-3">Habilidade</th><th className="px-3 py-3">Dificuldade</th><th className="px-3 py-3">Gabarito</th><th className="px-3 py-3" /></tr></thead><tbody>{questionsQuery.data.map((question) => <tr key={question.id} className="border-b border-border/60 last:border-0"><td className="max-w-md px-3 py-4"><p className="font-bold text-primary">Q{String(question.id).padStart(2, "0")}</p><p className="mt-1 truncate text-xs text-muted-foreground">{question.statement}</p></td><td className="px-3 py-4 text-muted-foreground">{subjectsQuery.data?.find((subject) => subject.id === question.subjectId)?.name || "—"}</td><td className="px-3 py-4 text-muted-foreground">{question.skill || "—"}</td><td className="px-3 py-4"><Badge variant="secondary" className="rounded-full">{question.difficulty === "easy" ? "Fácil" : question.difficulty === "hard" ? "Difícil" : "Média"}</Badge></td><td className="px-3 py-4 font-bold text-primary">{question.correctAnswer}</td><td className="px-3 py-4 text-right"><Button variant="ghost" size="icon" className="rounded-full"><MoreHorizontal className="h-4 w-4" /></Button></td></tr>)}</tbody></table></div> : <EmptyState icon={BookOpen} title="Seu banco está vazio" text="Cadastre questões para começar a criar avaliações com mais agilidade." />}</SectionCard>
  </div>;
}

function StudentsPage() {
  const [tab, setTab] = useState<"students" | "classes">("students");
  const studentsQuery = trpc.admin.students.list.useQuery();
  const classesQuery = trpc.admin.classes.list.useQuery();
  const schoolsQuery = trpc.admin.schools.list.useQuery();
  const teachersQuery = trpc.admin.teachers.list.useQuery();
  const utils = trpc.useUtils();
  const [showForm, setShowForm] = useState(false);
  const [studentForm, setStudentForm] = useState({ name: "", cpf: "", schoolId: "", classId: "" });
  const [classForm, setClassForm] = useState({ name: "", grade: "5º Ano", schoolId: "", teacherId: "", year: String(new Date().getFullYear()) });
  const createStudent = trpc.admin.students.create.useMutation({ onSuccess: () => { setShowForm(false); setStudentForm({ name: "", cpf: "", schoolId: "", classId: "" }); void utils.admin.students.list.invalidate(); } });
  const createClass = trpc.admin.classes.create.useMutation({ onSuccess: () => { setShowForm(false); setClassForm({ name: "", grade: "5º Ano", schoolId: "", teacherId: "", year: String(new Date().getFullYear()) }); void utils.admin.classes.list.invalidate(); } });
  const updateStudentStatus = trpc.admin.students.update.useMutation({ onSuccess: () => void utils.admin.students.list.invalidate() });
  const classesBySchool = classesQuery.data?.filter((classRow) => !studentForm.schoolId || classRow.schoolId === Number(studentForm.schoolId)) ?? [];
  return <div><PageHeader eyebrow="Comunidade escolar" title="Alunos e turmas" description="Mantenha a estrutura da escola organizada para que cada resultado tenha o contexto correto." action={<Button className="rounded-full" onClick={() => setShowForm((value) => !value)}><Plus className="mr-2 h-4 w-4" /> {tab === "students" ? "Novo aluno" : "Nova turma"}</Button>} />
    <div className="mb-5 flex w-fit gap-1 rounded-full bg-muted p-1"><button className={`rounded-full px-4 py-2 text-sm font-bold ${tab === "students" ? "bg-card text-primary shadow-sm" : "text-muted-foreground"}`} onClick={() => setTab("students")}>Alunos</button><button className={`rounded-full px-4 py-2 text-sm font-bold ${tab === "classes" ? "bg-card text-primary shadow-sm" : "text-muted-foreground"}`} onClick={() => setTab("classes")}>Turmas</button></div>
    {showForm && tab === "students" ? <SectionCard className="mb-5 border-primary/20"><div className="mb-5"><p className="text-sm font-extrabold text-primary">Cadastrar aluno</p><p className="mt-1 text-xs text-muted-foreground">O CPF será armazenado de forma restrita e exibido mascarado.</p></div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Nome completo</Label><Input value={studentForm.name} onChange={(event) => setStudentForm({ ...studentForm, name: event.target.value })} placeholder="Nome do aluno" /></div><div className="space-y-2"><Label>CPF</Label><Input value={studentForm.cpf} onChange={(event) => setStudentForm({ ...studentForm, cpf: event.target.value.replace(/\D/g, "").slice(0, 11) })} placeholder="Somente números" type="password" /></div><div className="space-y-2"><Label>Escola</Label><select value={studentForm.schoolId} onChange={(event) => setStudentForm({ ...studentForm, schoolId: event.target.value, classId: "" })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Selecione</option>{schoolsQuery.data?.map((school) => <option key={school.id} value={school.id}>{school.name}</option>)}</select></div><div className="space-y-2"><Label>Turma</Label><select value={studentForm.classId} onChange={(event) => setStudentForm({ ...studentForm, classId: event.target.value })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Selecione</option>{classesBySchool.map((classRow) => <option key={classRow.id} value={classRow.id}>{classRow.name} · {classRow.year}</option>)}</select></div></div><div className="mt-6 flex justify-end gap-3"><Button variant="outline" className="rounded-full" onClick={() => setShowForm(false)}>Cancelar</Button><Button className="rounded-full" disabled={createStudent.isPending || !studentForm.name || studentForm.cpf.length !== 11 || !studentForm.schoolId || !studentForm.classId} onClick={() => createStudent.mutate({ name: studentForm.name, cpf: studentForm.cpf, schoolId: Number(studentForm.schoolId), classId: Number(studentForm.classId) })}>{createStudent.isPending ? "Salvando…" : "Cadastrar aluno"}</Button></div></SectionCard> : null}{showForm && tab === "classes" ? <SectionCard className="mb-5 border-primary/20"><div className="mb-5"><p className="text-sm font-extrabold text-primary">Cadastrar turma</p><p className="mt-1 text-xs text-muted-foreground">Vincule a turma a uma escola e ao professor responsável.</p></div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Nome da turma</Label><Input value={classForm.name} onChange={(event) => setClassForm({ ...classForm, name: event.target.value })} placeholder="5º Ano A" /></div><div className="space-y-2"><Label>Ano letivo</Label><Input type="number" value={classForm.year} onChange={(event) => setClassForm({ ...classForm, year: event.target.value })} /></div><div className="space-y-2"><Label>Escola</Label><select value={classForm.schoolId} onChange={(event) => setClassForm({ ...classForm, schoolId: event.target.value, teacherId: "" })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Selecione</option>{schoolsQuery.data?.map((school) => <option key={school.id} value={school.id}>{school.name}</option>)}</select></div><div className="space-y-2"><Label>Professor responsável</Label><select value={classForm.teacherId} onChange={(event) => setClassForm({ ...classForm, teacherId: event.target.value })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Selecione</option>{teachersQuery.data?.filter((teacher) => !classForm.schoolId || teacher.schoolId === Number(classForm.schoolId)).map((teacher) => <option key={teacher.id} value={teacher.id}>{teacher.name}</option>)}</select></div></div><div className="mt-5 flex justify-end gap-3"><Button variant="outline" className="rounded-full" onClick={() => setShowForm(false)}>Cancelar</Button><Button className="rounded-full" disabled={createClass.isPending || !classForm.name || !classForm.schoolId || !classForm.teacherId} onClick={() => createClass.mutate({ name: classForm.name, grade: classForm.grade, schoolId: Number(classForm.schoolId), teacherId: Number(classForm.teacherId), year: Number(classForm.year) })}>{createClass.isPending ? "Salvando…" : "Cadastrar turma"}</Button></div></SectionCard> : null}
    {tab === "students" ? <SectionCard><div className="mb-5 flex items-center justify-between"><div><p className="text-sm font-extrabold text-primary">Alunos cadastrados</p><p className="mt-1 text-xs text-muted-foreground">{studentsQuery.data?.length ?? 0} alunos ativos</p></div><Button variant="outline" className="hidden rounded-full text-xs sm:flex"><Download className="mr-2 h-3.5 w-3.5" /> Importar CSV</Button></div>{studentsQuery.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead><tr className="border-b border-border/70 text-xs uppercase tracking-[0.12em] text-muted-foreground"><th className="px-3 py-3">Aluno</th><th className="px-3 py-3">CPF</th><th className="px-3 py-3">Escola</th><th className="px-3 py-3">Turma</th><th className="px-3 py-3">Status</th><th className="px-3 py-3" /></tr></thead><tbody>{studentsQuery.data.map((student) => { const classRow = classesQuery.data?.find((classItem) => classItem.id === student.classId); const school = schoolsQuery.data?.find((schoolItem) => schoolItem.id === student.schoolId); return <tr key={student.id} className="border-b border-border/60 last:border-0"><td className="px-3 py-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-secondary text-primary"><GraduationCap className="h-4 w-4" /></div><span className="font-bold text-primary">{student.name}</span></div></td><td className="px-3 py-4 font-mono text-xs text-muted-foreground">{maskCpf(student.cpf)}</td><td className="px-3 py-4 text-muted-foreground">{school?.name || "—"}</td><td className="px-3 py-4 text-muted-foreground">{classRow?.name || "—"}</td><td className="px-3 py-4"><Badge variant="secondary" className="rounded-full">{student.status === "active" ? "Ativo" : "Inativo"}</Badge></td><td className="px-3 py-4 text-right"><Button variant="ghost" size="sm" className="rounded-full text-xs font-bold text-primary" onClick={() => updateStudentStatus.mutate({ id: student.id, status: student.status === "active" ? "inactive" : "active" })}>{student.status === "active" ? "Arquivar" : "Reativar"}</Button></td></tr>; })}</tbody></table></div> : <EmptyState icon={GraduationCap} title="Nenhum aluno cadastrado" text="Adicione alunos para que eles possam ser identificados na aplicação das avaliações." />}</SectionCard> : <SectionCard><div className="mb-5 flex items-center justify-between"><div><p className="text-sm font-extrabold text-primary">Turmas cadastradas</p><p className="mt-1 text-xs text-muted-foreground">{classesQuery.data?.length ?? 0} turmas no ambiente</p></div><Button className="rounded-full" size="sm" onClick={() => setShowForm(true)}><Plus className="mr-2 h-3.5 w-3.5" /> Nova turma</Button></div>{classesQuery.data?.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{classesQuery.data.map((classRow) => <div key={classRow.id} className="lift-on-hover rounded-2xl border border-border/70 bg-background p-5"><div className="flex items-start justify-between"><div className="grid h-10 w-10 place-items-center rounded-xl bg-secondary text-primary"><UsersRound className="h-5 w-5" /></div><Badge variant="secondary" className="rounded-full">{classRow.year}</Badge></div><p className="mt-5 font-[Manrope] text-lg font-extrabold text-primary">{classRow.name}</p><p className="mt-1 text-sm text-muted-foreground">{classRow.grade} · {teachersQuery.data?.find((teacher) => teacher.id === classRow.teacherId)?.name || "Professor não vinculado"}</p><div className="mt-4 flex items-center gap-2 text-xs font-semibold text-muted-foreground"><School className="h-3.5 w-3.5" /> {schoolsQuery.data?.find((school) => school.id === classRow.schoolId)?.name || "Escola não encontrada"}</div></div>)}</div> : <EmptyState icon={UsersRound} title="Nenhuma turma cadastrada" text="Crie turmas e vincule os professores responsáveis." />}</SectionCard>}
  </div>;
}

function StudentDetail({ studentId, onBack }: { studentId: number; onBack: () => void }) {
  const detailQuery = trpc.teacher.studentResult.useQuery({ id: studentId });
  const data = detailQuery.data;
  const history = data?.results.slice().reverse().map((row, index) => ({ name: row.assessment?.name?.slice(0, 16) || `Avaliação ${index + 1}`, percentage: Number(row.attempt.percentage) })) ?? [];
  return <div className="mb-5"><Button variant="ghost" className="mb-4 rounded-full px-2 text-primary" onClick={onBack}><ChevronLeft className="mr-1 h-4 w-4" /> Voltar para resultados</Button>{detailQuery.isLoading ? <SectionCard><div className="p-8 text-center text-sm text-muted-foreground">Carregando resultado individual…</div></SectionCard> : data ? <><SectionCard className="mb-5 overflow-hidden p-0"><div className="bg-primary p-6 text-primary-foreground sm:p-8"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-white/60">Resultado individual</p><h2 className="mt-2 text-3xl font-extrabold tracking-tight">{data.student.name}</h2><p className="mt-2 text-sm text-white/65">CPF {data.student.cpf} · {data.results[0]?.classRow?.name || "Turma não informada"}</p></div><Badge className="w-fit rounded-full bg-white/12 text-white hover:bg-white/12">{data.results.length} avaliação(ões)</Badge></div></div><div className="grid gap-4 p-6 sm:grid-cols-3 sm:p-8">{[{ label: "Média histórica", value: `${(data.results.reduce((sum, row) => sum + Number(row.attempt.percentage), 0) / (data.results.length || 1)).toFixed(1)}%` }, { label: "Melhor resultado", value: `${Math.max(...data.results.map((row) => Number(row.attempt.percentage)), 0).toFixed(0)}%` }, { label: "Última nota", value: `${Number(data.results[0]?.attempt.score ?? 0).toFixed(1).replace(".", ",")}` }].map((item) => <div key={item.label} className="rounded-2xl bg-muted/60 p-4"><p className="text-xs font-bold uppercase tracking-[0.12em] text-muted-foreground">{item.label}</p><p className="mt-2 font-[Manrope] text-2xl font-extrabold text-primary">{item.value}</p></div>)}</div></SectionCard><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><SectionCard><div className="mb-5"><p className="text-sm font-extrabold text-primary">Evolução histórica</p><p className="mt-1 text-xs text-muted-foreground">Acompanhamento do aproveitamento ao longo das avaliações</p></div>{history.length > 1 ? <div className="h-[230px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={history} margin={{ left: -20, right: 8, top: 10, bottom: 0 }}><defs><linearGradient id="studentEvolution" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="oklch(0.55 0.12 192)" stopOpacity={0.35} /><stop offset="100%" stopColor="oklch(0.55 0.12 192)" stopOpacity={0.02} /></linearGradient></defs><CartesianGrid vertical={false} strokeDasharray="3 3" stroke="oklch(0.85 0.02 232)" /><XAxis dataKey="name" tick={{ fontSize: 10, fill: "oklch(0.5 0.03 232)" }} axisLine={false} tickLine={false} /><YAxis domain={[0, 100]} tickFormatter={(value) => `${value}%`} tick={{ fontSize: 10, fill: "oklch(0.5 0.03 232)" }} axisLine={false} tickLine={false} /><ChartTooltip formatter={(value) => [`${value}%`, "Aproveitamento"]} contentStyle={{ borderRadius: 14, border: "1px solid oklch(0.89 0.018 232)" }} /><Area type="monotone" dataKey="percentage" stroke="oklch(0.55 0.12 192)" strokeWidth={3} fill="url(#studentEvolution)" /></AreaChart></ResponsiveContainer></div> : <EmptyState icon={LineChart} title="Ainda não há histórico suficiente" text="A evolução aparecerá após o aluno concluir mais de uma avaliação." />}</SectionCard><SectionCard><div className="mb-5"><p className="text-sm font-extrabold text-primary">Avaliações realizadas</p><p className="mt-1 text-xs text-muted-foreground">Registro cronológico do aluno</p></div><div className="space-y-3">{data.results.map((row) => <div key={row.attempt.id} className="flex items-center gap-3 rounded-2xl bg-muted/50 p-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-secondary text-primary"><ClipboardList className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-primary">{row.assessment?.name}</p><p className="mt-1 text-xs text-muted-foreground">{row.subject?.name} · {row.attempt.finishedAt ? new Date(row.attempt.finishedAt).toLocaleDateString("pt-BR") : "—"}</p></div><span className="text-sm font-extrabold text-primary">{Number(row.attempt.percentage).toFixed(0)}%</span></div>)}</div></SectionCard></div></> : <SectionCard><EmptyState icon={UserRound} title="Resultado não encontrado" text="O aluno pode não estar mais visível para o seu perfil." /></SectionCard>}</div>;
}

function ClassSummary({ classId, onBack }: { classId: number; onBack: () => void }) {
  const summaryQuery = trpc.teacher.classSummary.useQuery({ id: classId });
  const data = summaryQuery.data;
  return <div className="mb-5"><Button variant="ghost" className="mb-4 rounded-full px-2 text-primary" onClick={onBack}><ChevronLeft className="mr-1 h-4 w-4" /> Voltar para desempenho</Button>{summaryQuery.isLoading ? <SectionCard><div className="p-8 text-center text-sm text-muted-foreground">Carregando consolidação da turma…</div></SectionCard> : data ? <><SectionCard className="mb-5 overflow-hidden p-0"><div className="bg-primary p-6 text-primary-foreground sm:p-8"><p className="text-xs font-bold uppercase tracking-[0.16em] text-white/60">Consolidação pedagógica</p><h2 className="mt-2 text-3xl font-extrabold tracking-tight">{data.classRow.name}</h2><p className="mt-2 text-sm text-white/65">{data.classRow.grade} · {data.classRow.year} · Visão agregada sem exposição de CPF</p></div><div className="grid gap-4 p-6 sm:grid-cols-4 sm:p-8">{[{ label: "Alunos", value: data.totalStudents }, { label: "Participação", value: `${data.participation}%` }, { label: "Média geral", value: `${data.average}%` }, { label: "Tentativas", value: data.completedAttempts }].map((item) => <div key={item.label} className="rounded-2xl bg-muted/60 p-4"><p className="text-xs font-bold uppercase tracking-[0.12em] text-muted-foreground">{item.label}</p><p className="mt-2 font-[Manrope] text-2xl font-extrabold text-primary">{item.value}</p></div>)}</div></SectionCard><div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><SectionCard><div className="mb-5"><p className="text-sm font-extrabold text-primary">Distribuição de aproveitamento</p><p className="mt-1 text-xs text-muted-foreground">Quantidade de tentativas por faixa</p></div>{data.completedAttempts ? <div className="h-[250px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={data.distribution} margin={{ left: -20, right: 8, top: 10, bottom: 0 }}><CartesianGrid vertical={false} strokeDasharray="3 3" stroke="oklch(0.85 0.02 232)" /><XAxis dataKey="label" tick={{ fontSize: 10, fill: "oklch(0.5 0.03 232)" }} axisLine={false} tickLine={false} /><YAxis allowDecimals={false} tick={{ fontSize: 10, fill: "oklch(0.5 0.03 232)" }} axisLine={false} tickLine={false} /><ChartTooltip contentStyle={{ borderRadius: 14, border: "1px solid oklch(0.89 0.018 232)" }} /><Bar dataKey="value" name="Tentativas" radius={[8, 8, 0, 0]} fill="oklch(0.55 0.12 192)" /></BarChart></ResponsiveContainer></div> : <EmptyState icon={BarChart3} title="Sem resultados consolidados" text="A distribuição aparecerá após a primeira tentativa concluída." />}</SectionCard><SectionCard><div className="mb-5"><p className="text-sm font-extrabold text-primary">Evolução da turma</p><p className="mt-1 text-xs text-muted-foreground">Média por avaliação concluída</p></div>{data.evolution.length > 1 ? <div className="h-[250px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data.evolution} margin={{ left: -20, right: 8, top: 10, bottom: 0 }}><defs><linearGradient id="classEvolution" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="oklch(0.64 0.14 50)" stopOpacity={0.35} /><stop offset="100%" stopColor="oklch(0.64 0.14 50)" stopOpacity={0.02} /></linearGradient></defs><CartesianGrid vertical={false} strokeDasharray="3 3" stroke="oklch(0.85 0.02 232)" /><XAxis dataKey="name" tick={{ fontSize: 10, fill: "oklch(0.5 0.03 232)" }} axisLine={false} tickLine={false} /><YAxis domain={[0, 100]} tickFormatter={(value) => `${value}%`} tick={{ fontSize: 10, fill: "oklch(0.5 0.03 232)" }} axisLine={false} tickLine={false} /><ChartTooltip formatter={(value) => [`${value}%`, "Média"]} contentStyle={{ borderRadius: 14, border: "1px solid oklch(0.89 0.018 232)" }} /><Area type="monotone" dataKey="percentage" stroke="oklch(0.64 0.14 50)" strokeWidth={3} fill="url(#classEvolution)" /></AreaChart></ResponsiveContainer></div> : <EmptyState icon={LineChart} title="Histórico ainda curto" text="A evolução aparecerá após mais de uma avaliação concluída." />}</SectionCard></div></> : <SectionCard><EmptyState icon={UsersRound} title="Turma não encontrada" text="Selecione uma turma permitida para o seu perfil." /></SectionCard>}</div>;
}

function ResultsPage() {
  const classesQuery = trpc.teacher.classes.useQuery();
  const [selectedStudentId, setSelectedStudentId] = useState<number | null>(null);
  const [selectedClassSummaryId, setSelectedClassSummaryId] = useState<number | null>(null);
  const [classId, setClassId] = useState("");
  const [teacherId, setTeacherId] = useState("");
  const [skill, setSkill] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [minPercentage, setMinPercentage] = useState("");
  const [maxPercentage, setMaxPercentage] = useState("");
  const [search, setSearch] = useState("");
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const resultsFilter = useMemo(() => ({
    classId: classId ? Number(classId) : undefined,
    teacherId: teacherId ? Number(teacherId) : undefined,
    skill: skill || undefined,
    search: search || undefined,
    from: from ? new Date(`${from}T00:00:00`) : undefined,
    to: to ? new Date(`${to}T23:59:59`) : undefined,
    minPercentage: minPercentage ? Number(minPercentage) : undefined,
    maxPercentage: maxPercentage ? Number(maxPercentage) : undefined,
  }), [classId, teacherId, skill, search, from, to, minPercentage, maxPercentage]);
  const resultsQuery = trpc.teacher.results.useQuery(resultsFilter);
  const analysisQuery = trpc.teacher.questionAnalysis.useQuery();
  const filteredResults = resultsQuery.data ?? [];

  return <div>
    <PageHeader eyebrow="Leitura pedagógica" title="Desempenho" description="Explore resultados individuais, compare turmas e identifique as questões que merecem ser retomadas." action={<Button variant="outline" className="rounded-full border-primary/20" onClick={() => resultsQuery.refetch()}><RefreshCw className="mr-2 h-4 w-4" /> Atualizar</Button>} />
    {selectedStudentId ? <StudentDetail studentId={selectedStudentId} onBack={() => setSelectedStudentId(null)} /> : selectedClassSummaryId ? <ClassSummary classId={selectedClassSummaryId} onBack={() => setSelectedClassSummaryId(null)} /> : <>
      <SectionCard className="mb-5">
        <div className="flex flex-col gap-3 md:flex-row">
          <div className="relative flex-1"><Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" /><Input className="rounded-xl pl-9" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar aluno" /></div>
          <select value={classId} onChange={(event) => setClassId(event.target.value)} className="flex h-10 rounded-xl border border-input bg-background px-3 text-sm md:w-56"><option value="">Todas as turmas</option>{classesQuery.data?.map((classRow) => <option key={classRow.id} value={classRow.id}>{classRow.name}</option>)}</select>
          <Button variant="outline" className="rounded-xl" disabled={!classId} onClick={() => setSelectedClassSummaryId(classId ? Number(classId) : null)}><BarChart3 className="mr-2 h-4 w-4" /> Visão da turma</Button><Button variant="outline" className="rounded-xl" onClick={() => setAdvancedOpen((value) => !value)}><Filter className="mr-2 h-4 w-4" /> {advancedOpen ? "Ocultar filtros" : "Filtros avançados"}</Button>
        </div>
        {advancedOpen ? <div className="mt-4 grid gap-3 border-t border-border/70 pt-4 sm:grid-cols-2 lg:grid-cols-4">
          <div className="space-y-2"><Label>Professor</Label><Input value={teacherId} onChange={(event) => setTeacherId(event.target.value)} placeholder="ID do professor" /></div>
          <div className="space-y-2"><Label>Habilidade</Label><Input value={skill} onChange={(event) => setSkill(event.target.value)} placeholder="Ex.: EF05MA07" /></div>
          <div className="space-y-2"><Label>De</Label><Input type="date" value={from} onChange={(event) => setFrom(event.target.value)} /></div>
          <div className="space-y-2"><Label>Até</Label><Input type="date" value={to} onChange={(event) => setTo(event.target.value)} /></div>
          <div className="space-y-2"><Label>Aproveitamento mínimo</Label><Input type="number" min={0} max={100} value={minPercentage} onChange={(event) => setMinPercentage(event.target.value)} placeholder="0" /></div>
          <div className="space-y-2"><Label>Aproveitamento máximo</Label><Input type="number" min={0} max={100} value={maxPercentage} onChange={(event) => setMaxPercentage(event.target.value)} placeholder="100" /></div>
        </div> : null}
      </SectionCard>
      <div className="grid gap-5 xl:grid-cols-[1.15fr_.85fr]">
        <SectionCard>
          <div className="mb-5 flex items-start justify-between"><div><p className="text-sm font-extrabold text-primary">Resultados individuais</p><p className="mt-1 text-xs text-muted-foreground">{filteredResults.length} tentativas concluídas</p></div><FileBarChart className="h-5 w-5 text-primary" /></div>
          {filteredResults.length ? <div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead><tr className="border-b border-border/70 text-xs uppercase tracking-[0.12em] text-muted-foreground"><th className="px-3 py-3">Aluno</th><th className="px-3 py-3">Turma</th><th className="px-3 py-3">Disciplina</th><th className="px-3 py-3">Resultado</th><th className="px-3 py-3" /></tr></thead><tbody>{filteredResults.map((row) => <tr key={row.attempt.id} className="border-b border-border/60 last:border-0"><td className="px-3 py-4"><p className="font-bold text-primary">{row.student?.name}</p><p className="mt-1 font-mono text-[10px] text-muted-foreground">{maskCpf(row.student?.cpf)}</p></td><td className="px-3 py-4 text-muted-foreground">{row.classRow?.name}</td><td className="px-3 py-4 text-muted-foreground">{row.subject?.name}</td><td className="px-3 py-4"><div className="flex items-center gap-3"><span className={`font-extrabold ${Number(row.attempt.percentage) < 60 ? "text-destructive" : "text-primary"}`}>{Number(row.attempt.percentage).toFixed(0)}%</span><div className="hidden w-20 sm:block"><Progress value={Number(row.attempt.percentage)} className="h-1.5" /></div></div></td><td className="px-3 py-4 text-right"><Button size="sm" variant="ghost" className="rounded-full text-xs font-bold text-primary" onClick={() => setSelectedStudentId(row.student?.id ?? null)}>Detalhes</Button></td></tr>)}</tbody></table></div> : <EmptyState icon={FileBarChart} title="Nenhum resultado encontrado" text="Ajuste os filtros ou aguarde a conclusão das primeiras aplicações." />}
        </SectionCard>
        <SectionCard>
          <div className="mb-5"><p className="text-sm font-extrabold text-primary">Questões mais desafiadoras</p><p className="mt-1 text-xs text-muted-foreground">Itens com menor percentual de acerto</p></div>
          {analysisQuery.data?.length ? <div className="space-y-4">{analysisQuery.data.slice(0, 6).map((item) => <div key={item.questionId}><div className="mb-2 flex items-start justify-between gap-4"><div className="min-w-0"><p className="text-sm font-bold text-primary">Q{String(item.questionId).padStart(2, "0")}</p><p className="mt-1 truncate text-xs text-muted-foreground">{item.statement}</p></div><span className={`shrink-0 text-sm font-extrabold ${item.percentage < 60 ? "text-destructive" : "text-primary"}`}>{item.percentage}%</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${item.percentage < 60 ? "bg-destructive" : "bg-[oklch(0.64_0.14_50)]"}`} style={{ width: `${item.percentage}%` }} /></div><p className="mt-1 text-[11px] text-muted-foreground">{item.skill} · {item.correct} acertos em {item.total} respostas</p></div>)}</div> : <EmptyState icon={Target} title="Sem análise disponível" text="A análise por questão será construída a partir das respostas enviadas." />}
        </SectionCard>
      </div>
    </>}
  </div>;
}

function SchoolsPage() {
  const schoolsQuery = trpc.admin.schools.list.useQuery();
  const utils = trpc.useUtils();
  const [showForm, setShowForm] = useState(false);
  const [name, setName] = useState("");
  const [code, setCode] = useState("");
  const [search, setSearch] = useState("");
  const createMutation = trpc.admin.schools.create.useMutation({ onSuccess: () => { setName(""); setCode(""); setShowForm(false); void utils.admin.schools.list.invalidate(); } });
  const updateMutation = trpc.admin.schools.update.useMutation({ onSuccess: () => void utils.admin.schools.list.invalidate() });
  const filteredSchools = schoolsQuery.data?.filter((school) => !search || school.name.toLowerCase().includes(search.toLowerCase()) || school.code.toLowerCase().includes(search.toLowerCase())) ?? [];
  return <div><PageHeader eyebrow="Estrutura institucional" title="Escolas" description="Cadastre e acompanhe as unidades que fazem parte da sua operação de avaliação." action={<Button className="rounded-full" onClick={() => setShowForm((value) => !value)}><Plus className="mr-2 h-4 w-4" /> Nova escola</Button>} />{showForm ? <SectionCard className="mb-5 border-primary/20"><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Nome da escola</Label><Input value={name} onChange={(event) => setName(event.target.value)} placeholder="Escola Municipal…" /></div><div className="space-y-2"><Label>Código interno</Label><Input value={code} onChange={(event) => setCode(event.target.value.toUpperCase())} placeholder="EM-001" /></div></div><div className="mt-5 flex justify-end gap-3"><Button variant="outline" className="rounded-full" onClick={() => setShowForm(false)}>Cancelar</Button><Button className="rounded-full" disabled={createMutation.isPending || !name || !code} onClick={() => createMutation.mutate({ name, code })}>Salvar escola</Button></div></SectionCard> : null}<SectionCard><div className="mb-5 flex items-center justify-between gap-4"><div><p className="text-sm font-extrabold text-primary">Unidades cadastradas</p><p className="mt-1 text-xs text-muted-foreground">{filteredSchools.length} resultado(s)</p></div><div className="relative w-56"><Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" /><Input value={search} onChange={(event) => setSearch(event.target.value)} className="h-9 rounded-full pl-9" placeholder="Buscar escola" /></div></div>{filteredSchools.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filteredSchools.map((school) => <div key={school.id} className="lift-on-hover rounded-2xl border border-border/70 bg-background p-5"><div className="flex items-start justify-between"><div className="grid h-10 w-10 place-items-center rounded-xl bg-secondary text-primary"><School className="h-5 w-5" /></div><Badge variant="secondary" className="rounded-full">{school.code}</Badge></div><p className="mt-5 font-[Manrope] text-lg font-extrabold text-primary">{school.name}</p><p className="mt-1 text-sm text-muted-foreground">{school.status === "active" ? "Unidade ativa" : "Unidade inativa"}</p><Button variant="ghost" size="sm" className="mt-4 rounded-full px-0 text-xs font-bold text-primary" onClick={() => updateMutation.mutate({ id: school.id, status: school.status === "active" ? "inactive" : "active" })}>{school.status === "active" ? "Arquivar unidade" : "Reativar unidade"}</Button></div>)}</div> : <EmptyState icon={School} title="Nenhuma escola cadastrada" text="Cadastre a primeira unidade para começar a organizar a comunidade escolar." />}</SectionCard></div>;
}

function TeachersPage() {
  const teachersQuery = trpc.admin.teachers.list.useQuery();
  const schoolsQuery = trpc.admin.schools.list.useQuery();
  const utils = trpc.useUtils();
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ name: "", cpf: "", email: "", schoolId: "" });
  const [editingTeacherId, setEditingTeacherId] = useState<number | null>(null);
  const [editingForm, setEditingForm] = useState({ name: "", cpf: "", email: "", schoolId: "" });
  const createMutation = trpc.admin.teachers.create.useMutation({ onSuccess: () => { setForm({ name: "", cpf: "", email: "", schoolId: "" }); setShowForm(false); void utils.admin.teachers.list.invalidate(); } });
  const updateMutation = trpc.admin.teachers.update.useMutation({ onSuccess: () => { setEditingTeacherId(null); void utils.admin.teachers.list.invalidate(); } });
  const startEdit = (teacher: NonNullable<typeof teachersQuery.data>[number]) => { setEditingTeacherId(teacher.id); setEditingForm({ name: teacher.name, cpf: "", email: teacher.email ?? "", schoolId: String(teacher.schoolId) }); };
  useEffect(() => { if (new URLSearchParams(window.location.search).get("newTeacher") === "1") setShowForm(true); }, []);
  return <div><PageHeader eyebrow="Equipe pedagógica" title="Professores" description="Vincule professores às escolas e mantenha a governança dos dados por turma." action={<Button className="rounded-full" onClick={() => setShowForm((value) => !value)}><Plus className="mr-2 h-4 w-4" /> Novo professor</Button>} />{showForm ? <SectionCard className="mb-5 border-primary/20"><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Nome completo</Label><Input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></div><div className="space-y-2"><Label>CPF</Label><Input type="password" value={form.cpf} onChange={(event) => setForm({ ...form, cpf: event.target.value.replace(/\D/g, "").slice(0, 11) })} /></div><div className="space-y-2"><Label>E-mail</Label><Input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></div><div className="space-y-2"><Label>Escola</Label><select value={form.schoolId} onChange={(event) => setForm({ ...form, schoolId: event.target.value })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Selecione</option>{schoolsQuery.data?.map((school) => <option key={school.id} value={school.id}>{school.name}</option>)}</select></div></div><div className="mt-5 flex justify-end gap-3"><Button variant="outline" className="rounded-full" onClick={() => setShowForm(false)}>Cancelar</Button><Button className="rounded-full" disabled={createMutation.isPending || !form.name || form.cpf.length !== 11 || !form.schoolId} onClick={() => createMutation.mutate({ name: form.name, cpf: form.cpf, email: form.email || undefined, schoolId: Number(form.schoolId) })}>Salvar professor</Button></div></SectionCard> : null}{editingTeacherId ? <SectionCard className="mb-5 border-primary/20"><div className="mb-4 flex items-center justify-between"><div><p className="text-sm font-extrabold text-primary">Editar professor</p><p className="mt-1 text-xs text-muted-foreground">O CPF atual permanece protegido; preencha apenas se precisar substituí-lo.</p></div><Button variant="ghost" className="rounded-full" onClick={() => setEditingTeacherId(null)}>Cancelar</Button></div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Nome completo</Label><Input value={editingForm.name} onChange={(event) => setEditingForm({ ...editingForm, name: event.target.value })} /></div><div className="space-y-2"><Label>Novo CPF (opcional)</Label><Input type="password" value={editingForm.cpf} onChange={(event) => setEditingForm({ ...editingForm, cpf: event.target.value.replace(/\\D/g, "").slice(0, 11) })} placeholder="Deixe em branco para manter" /></div><div className="space-y-2"><Label>E-mail</Label><Input type="email" value={editingForm.email} onChange={(event) => setEditingForm({ ...editingForm, email: event.target.value })} /></div><div className="space-y-2"><Label>Escola</Label><select value={editingForm.schoolId} onChange={(event) => setEditingForm({ ...editingForm, schoolId: event.target.value })} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Selecione</option>{schoolsQuery.data?.map((school) => <option key={school.id} value={school.id}>{school.name}</option>)}</select></div></div><div className="mt-5 flex justify-end"><Button className="rounded-full" disabled={updateMutation.isPending || editingForm.name.length < 2 || !editingForm.schoolId} onClick={() => updateMutation.mutate({ id: editingTeacherId, name: editingForm.name, cpf: editingForm.cpf || undefined, email: editingForm.email || undefined, schoolId: Number(editingForm.schoolId) })}>Salvar alterações</Button></div></SectionCard> : null}<SectionCard>{teachersQuery.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[600px] text-left text-sm"><thead><tr className="border-b border-border/70 text-xs uppercase tracking-[0.12em] text-muted-foreground"><th className="px-3 py-3">Professor</th><th className="px-3 py-3">CPF</th><th className="px-3 py-3">Escola</th><th className="px-3 py-3">Status</th><th className="px-3 py-3" /></tr></thead><tbody>{teachersQuery.data.map((teacher) => <tr key={teacher.id} className="border-b border-border/60 last:border-0"><td className="px-3 py-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-secondary text-primary"><UserRound className="h-4 w-4" /></div><span className="font-bold text-primary">{teacher.name}</span></div></td><td className="px-3 py-4 font-mono text-xs text-muted-foreground">{maskCpf(teacher.cpf)}</td><td className="px-3 py-4 text-muted-foreground">{schoolsQuery.data?.find((school) => school.id === teacher.schoolId)?.name || "—"}</td><td className="px-3 py-4"><Badge variant="secondary" className="rounded-full">{teacher.status === "active" ? "Ativo" : "Inativo"}</Badge></td><td className="px-3 py-4 text-right"><div className="flex justify-end gap-1"><Button variant="ghost" size="sm" className="rounded-full text-xs font-bold text-primary" onClick={() => startEdit(teacher)}>Editar</Button><Button variant="ghost" size="sm" className="rounded-full text-xs font-bold text-primary" onClick={() => updateMutation.mutate({ id: teacher.id, status: teacher.status === "active" ? "inactive" : "active" })}>{teacher.status === "active" ? "Arquivar" : "Reativar"}</Button></div></td></tr>)}</tbody></table></div> : <EmptyState icon={Users} title="Nenhum professor cadastrado" text="Cadastre professores para vincular turmas e garantir a visibilidade correta dos dados." />}</SectionCard></div>;
}

function ReportsPage() {
  const { user } = useAuth();
  const isAdmin = user?.role === "admin";
  const schoolsQuery = trpc.admin.schools.list.useQuery(undefined, { enabled: isAdmin });
  const classesQuery = trpc.admin.classes.list.useQuery(undefined, { enabled: isAdmin });
  const teachersQuery = trpc.admin.teachers.list.useQuery(undefined, { enabled: isAdmin });
  const subjectsQuery = trpc.admin.subjects.list.useQuery(undefined, { enabled: isAdmin });
  const assessmentsQuery = trpc.admin.assessments.list.useQuery(undefined, { enabled: isAdmin });
  const [reportType, setReportType] = useState<"general" | "class" | "student">("general");
  const [filters, setFilters] = useState({ schoolId: "", classId: "", teacherId: "", subjectId: "", assessmentId: "", skill: "", search: "", from: "", to: "", minPercentage: "", maxPercentage: "" });
  const input = useMemo(() => ({ reportType, schoolId: filters.schoolId ? Number(filters.schoolId) : undefined, classId: filters.classId ? Number(filters.classId) : undefined, teacherId: filters.teacherId ? Number(filters.teacherId) : undefined, subjectId: filters.subjectId ? Number(filters.subjectId) : undefined, assessmentId: filters.assessmentId ? Number(filters.assessmentId) : undefined, skill: filters.skill || undefined, search: filters.search || undefined, from: filters.from ? new Date(`${filters.from}T00:00:00`) : undefined, to: filters.to ? new Date(`${filters.to}T23:59:59`) : undefined, minPercentage: filters.minPercentage ? Number(filters.minPercentage) : undefined, maxPercentage: filters.maxPercentage ? Number(filters.maxPercentage) : undefined }), [reportType, filters]);
  const reportQuery = trpc.reports.useQuery(input);
  const rows = reportQuery.data ?? [];
  const update = (key: keyof typeof filters, value: string) => setFilters((current) => ({ ...current, [key]: value }));
  const exportCsv = () => { if (!rows.length) return; const headers = Object.keys(rows[0]); const csv = [headers.join(","), ...rows.map((row) => headers.map((header) => `"${String(row[header as keyof typeof row] ?? "").replace(/"/g, '""')}"`).join(","))].join("\n"); const blob = new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8;" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `relatorio-avalia-5-ano-${reportType}.csv`; anchor.click(); URL.revokeObjectURL(url); };
  const exportPdf = () => { if (!rows.length) return; const printWindow = window.open("", "_blank", "width=1000,height=760"); if (!printWindow) return; const body = rows.map((row) => `<tr>${Object.values(row).map((value) => `<td>${String(value ?? "").replace(/[&<>]/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[character] ?? character))}</td>`).join("")}</tr>`).join(""); printWindow.document.write(`<html><head><title>Relatório Avalia 5º Ano</title><style>body{font-family:Arial,sans-serif;padding:32px;color:#17324d}h1{font-size:22px}p{color:#667085}table{border-collapse:collapse;width:100%;font-size:11px;margin-top:24px}th,td{border:1px solid #d8e0e7;padding:7px;text-align:left}th{background:#eef5f3} @media print{button{display:none}}</style></head><body><h1>Relatório ${reportType === "student" ? "individual" : reportType === "class" ? "por turma" : "geral"} — Avalia 5º Ano</h1><p>Gerado em ${new Date().toLocaleString("pt-BR")}. CPF exibido de forma mascarada.</p><table><thead><tr>${Object.keys(rows[0]).map((key) => `<th>${key}</th>`).join("")}</tr></thead><tbody>${body}</tbody></table><script>window.onload=()=>window.print()</script></body></html>`); printWindow.document.close(); };
  return <div><PageHeader eyebrow="Prestação de contas" title="Relatórios" description="Exporte resultados filtrados para compartilhar evidências com a equipe pedagógica e a gestão escolar." action={<div className="flex gap-2"><Button variant="outline" className="rounded-full" disabled={!rows.length} onClick={exportCsv}><Download className="mr-2 h-4 w-4" /> CSV</Button><Button className="rounded-full" disabled={!rows.length} onClick={exportPdf}><FileText className="mr-2 h-4 w-4" /> PDF</Button></div>} />
    <SectionCard className="mb-5"><div className="mb-5 flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-secondary text-primary"><Filter className="h-5 w-5" /></div><div><p className="text-sm font-extrabold text-primary">{reportType === "student" ? "Relatório individual" : reportType === "class" ? "Relatório por turma" : "Relatório geral filtrado"}</p><p className="mt-1 text-xs text-muted-foreground">Combine dimensões e escolha o formato do relatório antes de exportar.</p></div></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><div className="space-y-2"><Label>Tipo de relatório</Label><select value={reportType} onChange={(event) => setReportType(event.target.value as "general" | "class" | "student")} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="general">Geral filtrado</option><option value="class">Consolidado por turma</option><option value="student">Individual por aluno</option></select></div><div className="space-y-2"><Label>Escola</Label><select value={filters.schoolId} onChange={(event) => update("schoolId", event.target.value)} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Todas</option>{schoolsQuery.data?.map((school) => <option key={school.id} value={school.id}>{school.name}</option>)}</select></div><div className="space-y-2"><Label>Turma</Label><select value={filters.classId} onChange={(event) => update("classId", event.target.value)} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Todas</option>{classesQuery.data?.map((classRow) => <option key={classRow.id} value={classRow.id}>{classRow.name}</option>)}</select></div><div className="space-y-2"><Label>Professor</Label><select value={filters.teacherId} onChange={(event) => update("teacherId", event.target.value)} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Todos</option>{teachersQuery.data?.map((teacher) => <option key={teacher.id} value={teacher.id}>{teacher.name}</option>)}</select></div><div className="space-y-2"><Label>Disciplina</Label><select value={filters.subjectId} onChange={(event) => update("subjectId", event.target.value)} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Todas</option>{subjectsQuery.data?.map((subject) => <option key={subject.id} value={subject.id}>{subject.name}</option>)}</select></div><div className="space-y-2"><Label>Avaliação</Label><select value={filters.assessmentId} onChange={(event) => update("assessmentId", event.target.value)} className="flex h-10 w-full rounded-xl border border-input bg-background px-3 text-sm"><option value="">Todas</option>{assessmentsQuery.data?.map((assessment) => <option key={assessment.id} value={assessment.id}>{assessment.name}</option>)}</select></div><div className="space-y-2"><Label>Habilidade</Label><Input value={filters.skill} onChange={(event) => update("skill", event.target.value)} placeholder="Ex.: EF05MA07" /></div><div className="space-y-2"><Label>Buscar aluno</Label><Input value={filters.search} onChange={(event) => update("search", event.target.value)} placeholder="Nome do aluno" /></div><div className="space-y-2"><Label>Período inicial</Label><Input type="date" value={filters.from} onChange={(event) => update("from", event.target.value)} /></div><div className="space-y-2"><Label>Período final</Label><Input type="date" value={filters.to} onChange={(event) => update("to", event.target.value)} /></div><div className="grid grid-cols-2 gap-2"><div className="space-y-2"><Label>Mín. %</Label><Input type="number" min={0} max={100} value={filters.minPercentage} onChange={(event) => update("minPercentage", event.target.value)} placeholder="0" /></div><div className="space-y-2"><Label>Máx. %</Label><Input type="number" min={0} max={100} value={filters.maxPercentage} onChange={(event) => update("maxPercentage", event.target.value)} placeholder="100" /></div></div></div></SectionCard>
    <SectionCard><div className="mb-5 flex items-center justify-between"><div><p className="text-sm font-extrabold text-primary">Prévia do relatório</p><p className="mt-1 text-xs text-muted-foreground">{rows.length} resultado(s) encontrados</p></div><span className="rounded-full bg-secondary px-3 py-1 text-xs font-bold text-primary">CPF protegido</span></div>{rows.length ? <div className="overflow-x-auto"><table className="w-full min-w-[940px] text-left text-xs"><thead><tr className="border-b border-border/70 uppercase tracking-[0.1em] text-muted-foreground">{Object.keys(rows[0]).map((key) => <th key={key} className="px-3 py-3 font-bold">{key}</th>)}</tr></thead><tbody>{rows.slice(0, 25).map((row, index) => <tr key={`${String(Object.values(row)[0] ?? "linha")}-${index}`} className="border-b border-border/60 last:border-0">{Object.values(row).map((value, valueIndex) => <td key={valueIndex} className="px-3 py-3 text-muted-foreground">{String(value ?? "—")}</td>)}</tr>)}</tbody></table></div> : <EmptyState icon={FileText} title="Nenhum dado para exportar" text="Ajuste os filtros ou aguarde avaliações concluídas para gerar o relatório." />}</SectionCard>
  </div>;
}

function SettingsPage() {
  const subjectsQuery = trpc.admin.subjects.list.useQuery();
  const utils = trpc.useUtils();
  const [showSubjectForm, setShowSubjectForm] = useState(false);
  const [subjectForm, setSubjectForm] = useState({ name: "", code: "" });
  const [editingSubjectId, setEditingSubjectId] = useState<number | null>(null);
  const [editingSubjectForm, setEditingSubjectForm] = useState({ name: "", code: "" });
  const createSubjectMutation = trpc.admin.subjects.create.useMutation({ onSuccess: () => { setSubjectForm({ name: "", code: "" }); setShowSubjectForm(false); void utils.admin.subjects.list.invalidate(); } });
  const updateSubjectMutation = trpc.admin.subjects.update.useMutation({ onSuccess: () => { setEditingSubjectId(null); void utils.admin.subjects.list.invalidate(); } });
  const startSubjectEdit = (subject: NonNullable<typeof subjectsQuery.data>[number]) => { setEditingSubjectId(subject.id); setEditingSubjectForm({ name: subject.name, code: subject.code }); };
  useEffect(() => { const requestedId = Number(new URLSearchParams(window.location.search).get("editSubject")); const subject = requestedId ? subjectsQuery.data?.find((item) => item.id === requestedId) : undefined; if (subject && editingSubjectId === null) startSubjectEdit(subject); }, [subjectsQuery.data, editingSubjectId]);
  return <div><PageHeader eyebrow="Preferências da plataforma" title="Configurações" description="Ajustes institucionais e regras de uso para manter a experiência consistente." /><div className="grid gap-5 lg:grid-cols-2"><SectionCard><div className="flex items-start gap-4"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-secondary text-primary"><Settings2 className="h-5 w-5" /></div><div><p className="font-extrabold text-primary">Política de privacidade</p><p className="mt-2 text-sm leading-6 text-muted-foreground">CPFs aparecem mascarados nas telas e exportações. O acesso a dados de alunos é condicionado ao perfil de cada usuário.</p><Badge className="mt-4 rounded-full bg-[oklch(0.93_0.035_165)] text-[oklch(0.3_0.08_165)] hover:bg-[oklch(0.93_0.035_165)]">Ativa</Badge></div></div></SectionCard><SectionCard><div className="flex items-start gap-4"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-accent text-accent-foreground"><ShieldIcon /></div><div><p className="font-extrabold text-primary">Perfis de acesso</p><p className="mt-2 text-sm leading-6 text-muted-foreground">Administradores enxergam toda a operação. Professores visualizam exclusivamente suas turmas, alunos e resultados vinculados.</p><Badge variant="secondary" className="mt-4 rounded-full">Controle ativo</Badge></div></div></SectionCard></div><SectionCard className="mt-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="text-sm font-extrabold text-primary">Disciplinas</p><p className="mt-1 text-xs text-muted-foreground">Mantenha o catálogo usado no banco de questões e nas avaliações.</p></div><Button className="w-fit rounded-full" onClick={() => setShowSubjectForm((value) => !value)}><Plus className="mr-2 h-4 w-4" /> Nova disciplina</Button></div>{showSubjectForm ? <div className="mt-5 grid gap-4 border-t border-border/70 pt-5 md:grid-cols-[1fr_180px_auto]"><div className="space-y-2"><Label>Nome</Label><Input value={subjectForm.name} onChange={(event) => setSubjectForm({ ...subjectForm, name: event.target.value })} placeholder="Ciências" /></div><div className="space-y-2"><Label>Código</Label><Input value={subjectForm.code} onChange={(event) => setSubjectForm({ ...subjectForm, code: event.target.value.toUpperCase() })} placeholder="CIE" /></div><Button className="self-end rounded-full" disabled={createSubjectMutation.isPending || subjectForm.name.length < 2 || subjectForm.code.length < 2} onClick={() => createSubjectMutation.mutate(subjectForm)}>Salvar</Button></div> : null}{editingSubjectId ? <div className="mt-5 grid gap-4 border-t border-border/70 pt-5 md:grid-cols-[1fr_180px_auto_auto]"><div className="space-y-2"><Label>Editar nome</Label><Input value={editingSubjectForm.name} onChange={(event) => setEditingSubjectForm({ ...editingSubjectForm, name: event.target.value })} /></div><div className="space-y-2"><Label>Editar código</Label><Input value={editingSubjectForm.code} onChange={(event) => setEditingSubjectForm({ ...editingSubjectForm, code: event.target.value.toUpperCase() })} /></div><Button variant="outline" className="self-end rounded-full" onClick={() => setEditingSubjectId(null)}>Cancelar</Button><Button className="self-end rounded-full" disabled={updateSubjectMutation.isPending || editingSubjectForm.name.length < 2 || editingSubjectForm.code.length < 2} onClick={() => updateSubjectMutation.mutate({ id: editingSubjectId, name: editingSubjectForm.name, code: editingSubjectForm.code })}>Salvar</Button></div> : null}{subjectsQuery.data?.length ? <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead><tr className="border-b border-border/70 text-xs uppercase tracking-[0.12em] text-muted-foreground"><th className="px-3 py-3">Disciplina</th><th className="px-3 py-3">Código</th><th className="px-3 py-3">Status</th><th className="px-3 py-3" /></tr></thead><tbody>{subjectsQuery.data.map((subject) => <tr key={subject.id} className="border-b border-border/60 last:border-0"><td className="px-3 py-4 font-bold text-primary">{subject.name}</td><td className="px-3 py-4 font-mono text-xs text-muted-foreground">{subject.code}</td><td className="px-3 py-4"><Badge variant="secondary" className="rounded-full">{subject.status === "active" ? "Ativa" : "Inativa"}</Badge></td><td className="px-3 py-4 text-right"><div className="flex justify-end gap-1"><Button variant="ghost" size="sm" className="rounded-full text-xs font-bold text-primary" onClick={() => startSubjectEdit(subject)}>Editar</Button><Button variant="ghost" size="sm" className="rounded-full text-xs font-bold text-primary" onClick={() => updateSubjectMutation.mutate({ id: subject.id, status: subject.status === "active" ? "inactive" : "active" })}>{subject.status === "active" ? "Arquivar" : "Reativar"}</Button></div></td></tr>)}</tbody></table></div> : <div className="mt-5"><EmptyState icon={BookOpen} title="Nenhuma disciplina cadastrada" text="Cadastre as áreas de conhecimento usadas pelas avaliações." /></div>}</SectionCard></div>;
}

function ShieldIcon() { return <svg viewBox="0 0 24 24" className="h-5 w-5" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M12 3 5 6v5c0 4.8 2.9 8.4 7 10 4.1-1.6 7-5.2 7-10V6l-7-3Z" /><path d="m9 12 2 2 4-4" /></svg>; }

export default function AdminDashboard() {
  const [location] = useLocation();
  let content: React.ReactNode = <DashboardHome />;
  if (location === "/admin/assessments") content = <AssessmentsPage />;
  if (location === "/admin/questions") content = <QuestionsPage />;
  if (location === "/admin/schools") content = <SchoolsPage />;
  if (location === "/admin/teachers") content = <TeachersPage />;
  if (location === "/admin/students") content = <StudentsPage />;
  if (location === "/admin/results") content = <ResultsPage />;
  if (location === "/admin/reports") content = <ReportsPage />;
  if (location === "/admin/settings") content = <SettingsPage />;
  return <DashboardLayout>{content}</DashboardLayout>;
}
